const data = $json || {};

const takeover = data.takeover_report || data.report || {};
const projectState = takeover.project_state || {};
const handoff = takeover.handoff || {};

const tasks = Array.isArray(takeover.current_tasks) ? takeover.current_tasks : [];
const problems = Array.isArray(takeover.known_problems) ? takeover.known_problems : [];
const solutions = Array.isArray(takeover.implemented_solutions) ? takeover.implemented_solutions : [];
const dependencies = Array.isArray(takeover.dependencies) ? takeover.dependencies : [];
const decisions = Array.isArray(takeover.decisions) ? takeover.decisions : [];
const recentActivity = Array.isArray(takeover.recent_activity) ? takeover.recent_activity : [];

const targetRole = data.target_role || takeover.target_role || 'New Team Member';
const previousOwner = data.previous_owner || takeover.previous_owner || null;

const context = {
  project: takeover.project || 'Context Recovery Engine',

  incoming_member: {
    role: targetRole,
    previous_owner: previousOwner
  },

  project_snapshot: {
    total_events: projectState.total_events || data.timeline_events || 0,
    total_evidence: projectState.total_evidence || data.evidence_count || 0,
    total_decisions: projectState.total_decisions || data.decision_count || 0,
    problems: projectState.problems || problems.length,
    solutions: projectState.solutions || solutions.length,
    tasks: projectState.tasks || tasks.length,
    dependencies: projectState.dependencies || dependencies.length,
    status_changes: projectState.status_changes || 0
  },

  current_tasks: tasks,
  known_problems: problems,
  implemented_solutions: solutions,
  dependencies: dependencies,
  important_decisions: decisions,
  recent_activity: recentActivity,

  recommended_start: [
    'Understand the current project state.',
    'Review important decisions before making architectural changes.',
    'Review known problems and existing solutions.',
    'Check dependencies before modifying connected components.',
    'Start with the highest-priority current task.'
  ]
};

return [
  {
    json: {
      status: 'handoff_context_created',
      target_role: targetRole,
      previous_owner: previousOwner,
      handoff_context: context
    }
  }
];

const data = $json || {};
const context = data.handoff_context || {};
const snapshot = context.project_snapshot || {};

const tasks = context.current_tasks || [];
const problems = context.known_problems || [];
const solutions = context.implemented_solutions || [];
const dependencies = context.dependencies || [];
const decisions = context.important_decisions || [];
const recentActivity = context.recent_activity || [];

const report = {
  handoff_title: 'Context Recovery — New Member Handoff',

  project: context.project || 'Context Recovery Engine',

  incoming_member: {
    role: context.incoming_member?.role || 'New Team Member',
    previous_owner: context.incoming_member?.previous_owner || null
  },

  project_snapshot: {
    events_recovered: snapshot.total_events || 0,
    evidence_recovered: snapshot.total_evidence || 0,
    decisions_recovered: snapshot.total_decisions || 0,
    open_tasks: snapshot.tasks || tasks.length,
    known_problems: snapshot.problems || problems.length,
    implemented_solutions: snapshot.solutions || solutions.length,
    dependencies: snapshot.dependencies || dependencies.length,
    status_changes: snapshot.status_changes || 0
  },

  executive_summary: {
    message: 'Historical project activity has been converted into structured context for the incoming team member.',
    what_was_recovered: [
      'Project events',
      'Evidence',
      'Tasks',
      'Problems',
      'Solutions',
      'Dependencies',
      'Important decisions'
    ],
    purpose: 'Reduce knowledge loss when a team member leaves and provide a role-specific project handoff.'
  },

  what_new_member_should_know: {
    current_tasks: tasks,
    known_problems: problems,
    implemented_solutions: solutions,
    important_decisions: decisions,
    dependencies: dependencies
  },

  recent_activity: recentActivity,

  first_actions: [
    'Review the project snapshot.',
    'Read important decisions before changing the architecture.',
    'Review known problems and implemented solutions.',
    'Check dependencies that may affect current work.',
    'Start with the highest-priority open task.'
  ],

  handoff_status: 'READY',
  generated_by: 'Context Recovery Engine'
};

return [
  {
    json: {
      status: 'success',
      handoff_report: report
    }
  }
];
